function parseCsvLine(line) {
  const csvSplitRegex = /,(?=(?:(?:[^"]*"){2})*[^"]*$)/;
  return line.split(csvSplitRegex).map((field) => {
    let cleanedField = field.trim();
    if (cleanedField.startsWith('"') && cleanedField.endsWith('"')) {
      cleanedField = cleanedField.substring(1, cleanedField.length - 1).replace(/""/g, '"');
    }
    return cleanedField;
  });
}

function parseTimestamp(ts) {
  const numericString = ts.replace(/[^0-9.]/g, "");
  const parts = numericString.split(".");
  const mainPart = parts[0];

  if (mainPart.length < 14) return null;

  const year = parseInt(mainPart.substring(0, 4), 10);
  const month = parseInt(mainPart.substring(4, 6), 10) - 1;
  const day = parseInt(mainPart.substring(6, 8), 10);
  const hour = parseInt(mainPart.substring(8, 10), 10);
  const minute = parseInt(mainPart.substring(10, 12), 10);
  const second = parseInt(mainPart.substring(12, 14), 10);
  const fractionalPart = parts.length > 1 ? parts[1] : "0";
  const millisecond = parseInt(fractionalPart.substring(0, 3).padEnd(3, "0"), 10);

  if ([year, month, day, hour, minute, second, millisecond].some(isNaN)) return null;

  const date = new Date(Date.UTC(year, month, day, hour, minute, second, millisecond));
  return isNaN(date.getTime()) ? null : date;
}

export function processLogFile(fileContent) {
  const lines = fileContent.split(/\r?\n/).filter((line) => line.trim() !== "");

  if (lines.length < 2) {
    return { error: "The sheet appears to be empty or contains only a header." };
  }

  const header = parseCsvLine(lines[0]).map((h) => h.trim().toLowerCase());
  const docIdIndex = header.indexOf("document id");
  const docVerIndex = header.indexOf("document version");
  const messageIndex = header.indexOf("message");
  const coCdIndex = header.indexOf("cocd");
  const timestampIndex = header.indexOf("timestamp");
  const typeIndex = header.indexOf("type");

  if (docIdIndex === -1) return { error: "Missing column: 'Document ID'" };
  if (coCdIndex === -1) return { error: "Missing column: 'CoCd'" };
  if (messageIndex === -1) return { error: "Missing column: 'Message'" };
  if (timestampIndex === -1) return { error: "Missing column: 'TimeStamp'" };
  if (typeIndex === -1) return { error: "Missing column: 'Type'" };

  const hasDocVer = docVerIndex !== -1;
  const grouped = new Map();

  const messages = {
    autoApproval: "Document assessment executed with the result Approval NOT required",
    secondApproval: "2nd Approval is mandated as document amount is",
    error: "An Error occured while determining the approvers",
    start: "Running the document assessment, based on outcome: proceed or end",
    end: "Completed execution of the Financial Approvals engine - technical success",
    wbsMissing: "Failed to identify WBS Element object owner for object",
    ccMissing: "Failed to identify Cost Center object owner for object",
    fallback: "Using HR Hierarchy data with key",
  };

  const thresholdRegex = /Threshold identified:[\s\S]*?\/(?<docType>[A-Z]{3,4})\s+values:/i;

  for (const line of lines.slice(1)) {
    const fields = parseCsvLine(line);
    if (fields.length <= Math.max(docIdIndex, messageIndex, coCdIndex, timestampIndex, typeIndex)) continue;

    const id = fields[docIdIndex]?.trim();
    const coCd = fields[coCdIndex]?.trim();
    if (!id || !coCd) continue;

    const ver = hasDocVer ? fields[docVerIndex]?.trim() ?? "" : "";
    const key = `${id}-${ver}-${coCd}`;
    const msg = fields[messageIndex]?.trim();
    const ts = parseTimestamp(fields[timestampIndex]?.trim());
    const type = fields[typeIndex]?.trim();

    if (!grouped.has(key)) {
      grouped.set(key, { entries: [], coCd, timestamps: [] });
    }

    const group = grouped.get(key);
    if (msg) group.entries.push({ message: msg, type, timestamp: ts });
    if (ts) group.timestamps.push(ts);
  }

  const runs = Array.from(grouped.entries()).map(([key, data]) => {
    const latest = data.timestamps.length ? new Date(Math.max(...data.timestamps.map((d) => d.getTime()))) : new Date(0);
    const startTime = data.entries.find((e) => e.message === messages.start)?.timestamp;
    const endTime = data.entries.find((e) => e.message === messages.end)?.timestamp;

    const run = {
      uniqueKey: key,
      companyCode: data.coCd,
      requestTypes: [],
      isIntercompany: false,
      isAutoApproved: false,
      isSecondLevelApproval: false,
      isErrorTransaction: false,
      isWbsOwnerMissing: false,
      isCostCenterOwnerMissing: false,
      isFallbackTransaction: false,
      transactionDate: latest,
      startTime: startTime || undefined,
      endTime: endTime || undefined,
    };

    const requestTypes = new Set();

    for (const { message, type } of data.entries) {
      const match = message.match(thresholdRegex);
      if (match?.groups?.docType) {
        requestTypes.add(match.groups.docType.toUpperCase());
      }

      if (message.includes("Intercompany supplier identified with supplier ID") && !message.includes("Non Intercompany")) {
        run.isIntercompany = true;
      }
      if (message === messages.autoApproval) run.isAutoApproved = true;
      if (message.startsWith(messages.secondApproval)) run.isSecondLevelApproval = true;
      if (message === messages.error && type === "E") run.isErrorTransaction = true;
      if (message.startsWith(messages.wbsMissing)) run.isWbsOwnerMissing = true;
      if (message.startsWith(messages.ccMissing)) run.isCostCenterOwnerMissing = true;
      if (message.startsWith(messages.fallback)) run.isFallbackTransaction = true;
    }

    run.requestTypes = Array.from(requestTypes);
    return run;
  });

  return { runs };
}
